// Saga orchestrator pseudo-code
class OrderSaga {
  async handleOrderCreated(event) {
    const { orderId, items, total } = event.data;

    const inventoryResult = await this.reserveInventory(orderId, items);
    if (!inventoryResult.success) {
      await this.compensateWithOrderCancelled(orderId);
      return;
    }

    const paymentResult = await this.authorizePayment(orderId, total);
    if (!paymentResult.success) {
      await this.releaseInventory(orderId, items);
      await this.compensateWithOrderCancelled(orderId);
      return;
    }

    await this.createShipping(orderId, event.data.shippingAddress);
    await this.completeOrder(orderId);
  }
}
```

